package com.antivirusalai.engine

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject
import java.io.ByteArrayOutputStream
import java.io.FileNotFoundException
import java.nio.charset.StandardCharsets
import kotlin.math.ln
import kotlin.math.roundToInt

/**
 * Lightweight on-device Random Forest inference.
 *
 * The model is generated by tools/train_multiview_model.py. No model is
 * silently fabricated: until a validated active-model.json is packaged,
 * inference explicitly reports NOT_CONFIGURED.
 */
data class MlScoringResult(
    val state: MlModelState,
    val riskScore: Int? = null,
    val threshold: Float? = null,
    val modelVersion: String? = null,
    val highRisk: Boolean = false,
    val topFeatures: List<String> = emptyList(),
    val errorCode: String? = null
)

internal data class MlTreeNode(
    val featureIndex: Int,
    val threshold: Float,
    val left: Int,
    val right: Int,
    val malwareScore: Float
)

internal data class MlDecisionTree(val nodes: List<MlTreeNode>) {
    fun predict(values: FloatArray, featureCounts: IntArray): Float {
        var index = 0
        repeat(nodes.size) {
            val node = nodes.getOrNull(index)
                ?: throw IllegalStateException("MODEL_NODE_INDEX_INVALID")
            if (node.featureIndex < 0) return node.malwareScore
            val value = values.getOrElse(node.featureIndex) { 0f }
            featureCounts[node.featureIndex]++
            index = if (value <= node.threshold) node.left else node.right
        }
        throw IllegalStateException("MODEL_TREE_CYCLE_OR_DEPTH_LIMIT")
    }
}

internal data class MlForestModel(
    val version: String,
    val threshold: Float,
    val featureNames: List<String>,
    val trees: List<MlDecisionTree>
) {
    fun predict(features: MlFeatureVector): Pair<Float, List<String>> {
        val vector = FloatArray(featureNames.size) { index ->
            val value = features.values[featureNames[index]] ?: 0f
            if (value.isFinite()) value else 0f
        }
        val usage = IntArray(featureNames.size)
        val score = trees.map { it.predict(vector, usage) }.average().toFloat()
        val top = featureNames.indices
            .filter { usage[it] > 0 }
            .sortedByDescending { usage[it] }
            .take(5)
            .map { featureNames[it] }
        return score.coerceIn(0f, 1f) to top
    }

    companion object {
        private const val MAX_TREES = 64
        private const val MAX_NODES_PER_TREE = 2_047
        private const val MAX_TOTAL_NODES = 131_072

        fun parse(json: String): MlForestModel {
            require(json.toByteArray(StandardCharsets.UTF_8).size <= 4 * 1024 * 1024) {
                "MODEL_SIZE_LIMIT"
            }
            val root = JSONObject(json)
            require(root.optString("format") == "ALAI-MV-FOREST/1") { "MODEL_FORMAT_UNSUPPORTED" }
            val version = root.optString("model_version")
            require(version.isNotBlank() && version.length <= 32) { "MODEL_VERSION_INVALID" }
            val threshold = root.optDouble("decision_threshold", Double.NaN).toFloat()
            require(threshold.isFinite() && threshold in 0f..1f) { "MODEL_THRESHOLD_INVALID" }

            val declaredFeatures = root.getJSONArray("features").toStringList()
            require(declaredFeatures == OnDeviceMlScorer.FEATURE_NAMES) { "MODEL_FEATURE_SCHEMA_MISMATCH" }

            val treeJson = root.getJSONArray("trees")
            require(treeJson.length() in 1..MAX_TREES) { "MODEL_TREE_COUNT_INVALID" }
            var totalNodes = 0
            val trees = ArrayList<MlDecisionTree>(treeJson.length())
            for (treeIndex in 0 until treeJson.length()) {
                val encodedNodes = treeJson.getJSONArray(treeIndex)
                require(encodedNodes.length() in 1..MAX_NODES_PER_TREE) { "MODEL_NODE_COUNT_INVALID" }
                totalNodes += encodedNodes.length()
                require(totalNodes <= MAX_TOTAL_NODES) { "MODEL_TOTAL_NODE_LIMIT" }
                val nodes = ArrayList<MlTreeNode>(encodedNodes.length())
                for (nodeIndex in 0 until encodedNodes.length()) {
                    val values = encodedNodes.getJSONArray(nodeIndex)
                    require(values.length() == 5) { "MODEL_NODE_SHAPE_INVALID" }
                    val feature = values.getInt(0)
                    val split = values.getDouble(1).toFloat()
                    val left = values.getInt(2)
                    val right = values.getInt(3)
                    val malwareScore = values.getDouble(4).toFloat()
                    require(split.isFinite() && malwareScore.isFinite() && malwareScore in 0f..1f) {
                        "MODEL_NODE_VALUE_INVALID"
                    }
                    if (feature < 0) {
                        require(left == -1 && right == -1) { "MODEL_LEAF_INVALID" }
                    } else {
                        require(feature < declaredFeatures.size) { "MODEL_FEATURE_INDEX_INVALID" }
                        require(left in 0 until encodedNodes.length() && right in 0 until encodedNodes.length()) {
                            "MODEL_CHILD_INDEX_INVALID"
                        }
                    }
                    nodes += MlTreeNode(feature, split, left, right, malwareScore)
                }
                require(nodes.first().featureIndex >= 0 || nodes.size == 1) { "MODEL_ROOT_INVALID" }
                trees += MlDecisionTree(nodes)
            }
            return MlForestModel(version, threshold, declaredFeatures, trees)
        }

        private fun JSONArray.toStringList(): List<String> =
            (0 until length()).map { getString(it) }
    }
}

object OnDeviceMlScorer {
    const val MODEL_ASSET = "ml/active-model.json"

    val FEATURE_NAMES = listOf(
        "apk_present",
        "file_size_mib",
        "target_sdk",
        "permission_count",
        "risky_permission_count",
        "debuggable",
        "exported_components",
        "accessibility_services",
        "permission_sms",
        "permission_install_packages",
        "permission_overlay",
        "permission_accessibility",
        "permission_device_admin",
        "permission_contacts",
        "permission_call_log",
        "permission_location",
        "permission_record_audio",
        "permission_camera",
        "permission_boot",
        "dex_sms_api",
        "dex_package_install_api",
        "dex_dynamic_code_loading",
        "dex_process_execution",
        "dex_accessibility_api",
        "dex_device_admin_api",
        "dex_network_api",
        "elf_execve_symbol",
        "elf_system_symbol",
        "elf_ptrace_symbol",
        "elf_dlopen_symbol",
        "archive_entry_count_log1p",
        "archive_expanded_mib",
        "archive_anomaly",
        "format_anomaly",
        "static_analysis_supported",
        "static_analysis_complete",
        "native_content_engine_complete"
    )

    @Volatile private var cachedModel: MlForestModel? = null
    @Volatile private var cachedFailure: String? = null
    @Volatile private var modelLoadAttempted = false

    fun extractFeatures(
        apk: ApkMetadata?,
        static: StaticAnalysisReport,
        combined: CombinedRiskAssessment,
        fileSizeBytes: Long,
        contentEngineState: ContentEngineState
    ): MlFeatureVector {
        val permissions = apk?.requestedPermissions.orEmpty()
        val evidenceCodes = static.evidence.map { it.code }.toSet()
        val categories = static.signalCategories
        val values = linkedMapOf<String, Float>()

        fun bit(value: Boolean) = if (value) 1f else 0f
        fun permission(vararg names: String) = names.any { it in permissions }
        fun evidence(vararg codes: String) = codes.any { it in evidenceCodes }
        fun category(vararg names: String) = names.any { it in categories }

        val riskyPermissions = setOf(
            "android.permission.READ_SMS",
            "android.permission.RECEIVE_SMS",
            "android.permission.SEND_SMS",
            "android.permission.READ_CONTACTS",
            "android.permission.READ_CALL_LOG",
            "android.permission.WRITE_CALL_LOG",
            "android.permission.REQUEST_INSTALL_PACKAGES",
            "android.permission.SYSTEM_ALERT_WINDOW",
            "android.permission.RECORD_AUDIO",
            "android.permission.ACCESS_FINE_LOCATION",
            "android.permission.ACCESS_BACKGROUND_LOCATION",
            "android.permission.READ_PHONE_STATE",
            "android.permission.RECEIVE_BOOT_COMPLETED"
        )
        values["apk_present"] = bit(apk != null)
        values["file_size_mib"] = fileSizeBytes.coerceAtLeast(0L).toFloat() / (1024f * 1024f)
        values["target_sdk"] = (apk?.targetSdk ?: 0).toFloat()
        values["permission_count"] = permissions.size.toFloat()
        values["risky_permission_count"] = permissions.count { it in riskyPermissions }.toFloat()
        values["debuggable"] = bit(apk?.debuggable == true)
        values["exported_components"] = (apk?.exportedComponentCount ?: 0).toFloat()
        values["accessibility_services"] = (apk?.declaredAccessibilityServiceCount ?: 0).toFloat()
        values["permission_sms"] = bit(permission(
            "android.permission.READ_SMS", "android.permission.RECEIVE_SMS", "android.permission.SEND_SMS"
        ))
        values["permission_install_packages"] = bit(permission("android.permission.REQUEST_INSTALL_PACKAGES"))
        values["permission_overlay"] = bit(permission("android.permission.SYSTEM_ALERT_WINDOW"))
        values["permission_accessibility"] = bit(
            (apk?.declaredAccessibilityServiceCount ?: 0) > 0 ||
                category("ACCESSIBILITY") || evidence("DEX_ACCESSIBILITY_API")
        )
        values["permission_device_admin"] = bit(category("DEVICE_ADMIN") || evidence("DEX_DEVICE_ADMIN_API"))
        values["permission_contacts"] = bit(permission("android.permission.READ_CONTACTS", "android.permission.WRITE_CONTACTS"))
        values["permission_call_log"] = bit(permission("android.permission.READ_CALL_LOG", "android.permission.WRITE_CALL_LOG"))
        values["permission_location"] = bit(permission(
            "android.permission.ACCESS_FINE_LOCATION",
            "android.permission.ACCESS_COARSE_LOCATION",
            "android.permission.ACCESS_BACKGROUND_LOCATION"
        ))
        values["permission_record_audio"] = bit(permission("android.permission.RECORD_AUDIO"))
        values["permission_camera"] = bit(permission("android.permission.CAMERA"))
        values["permission_boot"] = bit(permission("android.permission.RECEIVE_BOOT_COMPLETED"))

        values["dex_sms_api"] = bit(evidence("DEX_SMS_API_REFERENCE"))
        values["dex_package_install_api"] = bit(evidence("DEX_PACKAGE_INSTALL_API"))
        values["dex_dynamic_code_loading"] = bit(evidence("DEX_DYNAMIC_CODE_LOADING"))
        values["dex_process_execution"] = bit(evidence("DEX_PROCESS_BUILDER_API", "DEX_RUNTIME_API"))
        values["dex_accessibility_api"] = bit(evidence("DEX_ACCESSIBILITY_API"))
        values["dex_device_admin_api"] = bit(evidence("DEX_DEVICE_ADMIN_API"))
        values["dex_network_api"] = bit(evidence("DEX_SOCKET_API") || category("NETWORK_API"))
        values["elf_execve_symbol"] = bit(evidence("ELF_EXECVE_SYMBOL"))
        values["elf_system_symbol"] = bit(evidence("ELF_SYSTEM_SYMBOL"))
        values["elf_ptrace_symbol"] = bit(evidence("ELF_PTRACE_SYMBOL"))
        values["elf_dlopen_symbol"] = bit(evidence("ELF_DLOPEN_SYMBOL"))
        values["archive_entry_count_log1p"] = ln(1f + static.entryCount.coerceAtLeast(0).toFloat())
        values["archive_expanded_mib"] = static.expandedBytes.coerceAtLeast(0L).toFloat() / (1024f * 1024f)
        values["archive_anomaly"] = bit(category("ARCHIVE_ANOMALY"))
        values["format_anomaly"] = bit(category("FORMAT_ANOMALY"))
        values["static_analysis_supported"] = bit(static.supported)
        values["static_analysis_complete"] = bit(static.supported && static.complete)
        values["native_content_engine_complete"] = bit(contentEngineState == ContentEngineState.COMPLETE)

        // Feature schema deliberately excludes the heuristic's final verdict/score.
        // This reduces direct target leakage and keeps the learned model independent.
        @Suppress("UNUSED_VARIABLE") val independentGroups = combined.independentSignalGroups.size
        return MlFeatureVector(values.size, values)
    }

    fun score(context: Context, features: MlFeatureVector): MlScoringResult {
        val model = loadModel(context.applicationContext)
            ?: return MlScoringResult(
                state = if (cachedFailure == null) MlModelState.NOT_CONFIGURED else MlModelState.ERROR,
                errorCode = cachedFailure
            )
        return runCatching {
            val (rawScore, topFeatures) = model.predict(features)
            MlScoringResult(
                state = MlModelState.READY,
                riskScore = (rawScore * 100f).roundToInt().coerceIn(0, 100),
                threshold = model.threshold,
                modelVersion = model.version,
                highRisk = rawScore >= model.threshold,
                topFeatures = topFeatures
            )
        }.getOrElse {
            MlScoringResult(MlModelState.ERROR, errorCode = "MODEL_INFERENCE_FAILED")
        }
    }

    private fun loadModel(context: Context): MlForestModel? {
        if (modelLoadAttempted) return cachedModel
        synchronized(this) {
            if (modelLoadAttempted) return cachedModel
            modelLoadAttempted = true
            try {
                val bytes = context.assets.open(MODEL_ASSET).use { input ->
                    val output = ByteArrayOutputStream()
                    val buffer = ByteArray(8 * 1024)
                    var total = 0
                    while (true) {
                        val count = input.read(buffer)
                        if (count < 0) break
                        total += count
                        require(total <= 4 * 1024 * 1024) { "MODEL_SIZE_LIMIT" }
                        output.write(buffer, 0, count)
                    }
                    output.toByteArray()
                }
                cachedModel = MlForestModel.parse(String(bytes, StandardCharsets.UTF_8))
            } catch (_: FileNotFoundException) {
                cachedFailure = null
            } catch (_: Exception) {
                cachedFailure = "MODEL_ASSET_INVALID"
            }
            return cachedModel
        }
    }
}
